key_t sem_key = 0xDEADBEEF;

// 1. Create a new set of 2 semaphores (0600 permissions)
int nsems_create = 2;
int flags_create = IPC_CREAT | 0600;
int sem_id_new = semget(sem_key, nsems_create, flags_create);

// 2. Retrieve ID of an existing set (nsems must be 0)
int sem_id_existing = semget(sem_key, 0, 0);

// 3. Exclusive creation attempt
int flags_excl = IPC_CREAT | IPC_EXCL | 0666;
int sem_id_excl = semget(sem_key, 1, flags_excl);

// On error, semget returns -1
if (sem_id_new < 0) {
    perror("semget failed");
}
